package com.company.tpm.telegram;import java.time.Duration;import org.junit.jupiter.api.*;class TelegramLinkTokenServiceTest{@Test void tokenIsHashedAndMatches(){var s=new TelegramLinkTokenService();var g=s.generate(Duration.ofMinutes(10));Assertions.assertNotEquals(g.raw(),g.hash());Assertions.assertTrue(s.matches(g.raw(),g.hash()));Assertions.assertFalse(s.matches(g.raw()+"x",g.hash()));}}
